import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { GoogleLogin } from '@react-oauth/google'
import { useAuth } from '../context/AuthContext' // Path apne project structure ke hisab se verify kar lein

const Auth = () => {
  const navigate = useNavigate()
  const { login, register, loginWithGoogleCredential } = useAuth()

  const [isLogin, setIsLogin] = useState(true)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  })
  const [error, setError] = useState('')

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    })
  }

  // Handle Standard Form Submission (Email & Password)
  const handleSubmit = (e) => {
    e.preventDefault()
    setError('')

    try {
      if (isLogin) {
        const res = login(formData.email, formData.password)
        if (res.success) navigate('/')
      } else {
        const res = register(formData.email, formData.password, formData.name)
        if (res.success) navigate('/')
      }
    } catch (err) {
      setError(err.message || 'Authentication failed. Please try again.')
    }
  }

  // Handle Google OAuth Success
  const handleGoogleSuccess = (credentialResponse) => {
    try {
      if (credentialResponse.credential) {
        loginWithGoogleCredential(credentialResponse.credential)
        navigate('/')
      } else {
        setError('Google sign-in failed. No credentials returned.')
      }
    } catch (err) {
      console.error('Google Auth Error:', err)
      setError(err.message || 'Google sign-in failed.')
    }
  }

  // Handle Google OAuth Failure
  const handleGoogleError = () => {
    setError('Google sign-in popup was closed or failed.')
  }

  return (
    <div className="auth-container" style={styles.container}>
      <div className="auth-card" style={styles.card}>
        <h2>{isLogin ? 'Welcome Back' : 'Create Account'}</h2>
        <p style={styles.subtitle}>
          {isLogin ? 'Sign in to access your video rooms' : 'Get started with AuraChat'}
        </p>

        {error && <div style={styles.errorBanner}>{error}</div>}

        {/* Google OAuth Button */}
        <div style={styles.googleBtnContainer}>
          <GoogleLogin
            onSuccess={handleGoogleSuccess}
            onError={handleGoogleError}
            theme="filled_blue"
            size="large"
            width="100%"
          />
        </div>

        <div style={styles.divider}>
          <span>OR</span>
        </div>

        {/* Manual Email/Password Form */}
        <form onSubmit={handleSubmit} style={styles.form}>
          {!isLogin && (
            <div style={styles.inputGroup}>
              <label>Name</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                placeholder="Enter your name"
                required={!isLogin}
                style={styles.input}
              />
            </div>
          )}

          <div style={styles.inputGroup}>
            <label>Email</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Enter your email"
              required
              style={styles.input}
            />
          </div>

          <div style={styles.inputGroup}>
            <label>Password</label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleInputChange}
              placeholder="Enter your password"
              required
              style={styles.input}
            />
          </div>

          <button type="submit" style={styles.submitBtn}>
            {isLogin ? 'Sign In' : 'Sign Up'}
          </button>
        </form>

        <p style={styles.toggleText}>
          {isLogin ? "Don't have an account? " : 'Already have an account? '}
          <span
            onClick={() => {
              setIsLogin(!isLogin)
              setError('')
            }}
            style={styles.toggleLink}
          >
            {isLogin ? 'Sign Up' : 'Sign In'}
          </span>
        </p>
      </div>
    </div>
  )
}

// Inline Fallback Styles for Quick Layout
const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    backgroundColor: '#f5f7fb',
    padding: '20px',
  },
  card: {
    width: '100%',
    maxWidth: '400px',
    padding: '30px',
    backgroundColor: '#ffffff',
    borderRadius: '12px',
    boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
    textAlign: 'center',
  },
  subtitle: {
    color: '#666',
    fontSize: '14px',
    marginBottom: '20px',
  },
  errorBanner: {
    backgroundColor: '#ffebe9',
    color: '#d93025',
    padding: '10px',
    borderRadius: '6px',
    fontSize: '13px',
    marginBottom: '15px',
  },
  googleBtnContainer: {
    display: 'flex',
    justifyContent: 'center',
    marginBottom: '20px',
  },
  divider: {
    display: 'flex',
    alignItems: 'center',
    textAlign: 'center',
    margin: '20px 0',
    color: '#888',
    fontSize: '12px',
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '15px',
    textAlign: 'left',
  },
  inputGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '5px',
  },
  input: {
    padding: '10px 12px',
    borderRadius: '6px',
    border: '1px solid #ccc',
    fontSize: '14px',
  },
  submitBtn: {
    padding: '12px',
    borderRadius: '6px',
    border: 'none',
    backgroundColor: '#1a73e8',
    color: '#fff',
    fontSize: '15px',
    fontWeight: 'bold',
    cursor: 'pointer',
    marginTop: '10px',
  },
  toggleText: {
    marginTop: '20px',
    fontSize: '14px',
    color: '#555',
  },
  toggleLink: {
    color: '#1a73e8',
    cursor: 'pointer',
    fontWeight: 'bold',
  },
}

export default Auth
